#!/usr/bin/env python3
"""Convert local n8n JSON into a disabled YAML candidate; never contact a provider."""

from __future__ import annotations

import argparse
import json
import os
import sys
from pathlib import Path


def _write_new(path: Path, text: str) -> None:
    descriptor = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
    with os.fdopen(descriptor, "w", encoding="utf-8") as stream:
        stream.write(text)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("--workflow-id", required=True)
    parser.add_argument("--object-response-node", type=int, action="append", default=[])
    parser.add_argument("--parallel-fanout", action="store_true")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--report", type=Path)
    arguments = parser.parse_args()
    destinations = [arguments.output] + ([arguments.report] if arguments.report else [])
    if len({path.resolve() for path in destinations}) != len(destinations) or any(
        path.exists() or path.is_symlink() or not path.parent.is_dir() for path in destinations
    ):
        parser.exit(2, "Use distinct new output files in existing directories.\n")
    # Explicit local helper root also permits Python's isolated (-I) mode.
    sys.path.insert(0, str(Path(__file__).resolve().parent))
    try:
        from workflow_migration.n8n import convert_n8n
    except ModuleNotFoundError as error:
        if error.name != "yaml":
            raise
        parser.exit(2, "The converter requires PyYAML 6.x in this Python environment.\n")
    try:
        with arguments.source.open(encoding="utf-8") as stream:
            source = stream.read(1_000_001)
    except (OSError, UnicodeError):
        parser.exit(2, "Cannot read the source as UTF-8 JSON.\n")
    result = convert_n8n(
        source,
        workflow_id=arguments.workflow_id,
        object_response_nodes=arguments.object_response_node,
        parallel_fanout=arguments.parallel_fanout,
    )
    report = {key: value for key, value in result.items() if key != "bundle_yaml"}
    report_text = json.dumps(report, ensure_ascii=False, indent=2) + "\n"
    try:
        if result["bundle_yaml"] is not None:
            _write_new(arguments.output, result["bundle_yaml"])
        if arguments.report:
            _write_new(arguments.report, report_text)
        else:
            print(report_text, end="")
    except OSError:
        parser.exit(
            2, "Could not create a new output file; inspect destinations before retrying.\n"
        )
    return 0 if result["status"] == "converted" else 1


if __name__ == "__main__":
    raise SystemExit(main())

"""Strict bounded JSON parsing shared by source documents and literal parameters."""

from __future__ import annotations

import json
import math
from typing import Any


def _object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate object member")
        result[key] = value
    return result


def _constant(_: str) -> Any:
    raise ValueError("Nonfinite number")


def _float(text: str) -> float:
    value = float(text)
    if not math.isfinite(value):
        raise ValueError("Nonfinite number")
    return value


def load_json(text: str) -> Any:
    """Reject duplicate names, nonfinite numbers and excessive nesting."""
    result = json.loads(
        text, object_pairs_hook=_object, parse_constant=_constant, parse_float=_float
    )
    stack = [(result, 0)]
    while stack:
        value, depth = stack.pop()
        if depth > 64:
            raise ValueError("JSON nesting exceeds the conversion limit")
        if isinstance(value, dict):
            stack.extend((item, depth + 1) for item in value.values())
        elif isinstance(value, list):
            stack.extend((item, depth + 1) for item in value)
    return result

"""Map independent source branches to existing native Group Parallel Run lanes."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from .contracts import require
from .graph import SourceGraph
from .target import edge


@dataclass
class ParallelLayout:
    groups: list[dict[str, Any]] = field(default_factory=list)
    membership: dict[int, dict[str, str]] = field(default_factory=dict)
    forks: dict[int, str] = field(default_factory=dict)


def parallel_layout(graph: SourceGraph) -> ParallelLayout:
    """Each qualified branch is an independent linear lane, without hidden joins."""
    result = ParallelLayout()
    for source, starts in graph.fanouts.items():
        group_id = f"fanout_n{source:04d}"
        lanes = []
        for number, start in enumerate(starts):
            lane_id = f"branch_{number:04d}"
            lanes.append({"lane_id": lane_id, "entry": {"kind": "step", "id": f"n{start:04d}"}})
            current: int | None = start
            while current is not None:
                require(
                    current not in result.membership
                    and current not in graph.fanouts
                    and graph.nodes[current]["type"] != "n8n-nodes-base.if",
                    "parallel_branch_needs_mapping",
                    f"nodes[{current}]",
                    "This branch needs an explicit child-workflow or control-flow mapping.",
                    "Native Parallel Run groups are available; this adapter currently qualifies linear independent lanes. Map conditional/nested branches explicitly.",
                )
                result.membership[current] = {"group_id": group_id, "lane_id": lane_id}
                links = graph.links.get(current, [])
                current = links[0] if links else None
        result.groups.append(
            {
                "group_id": group_id,
                "display_name": "Parallel Run",
                "body": {"kind": "lanes", "lanes": lanes},
            }
        )
        result.forks[source] = group_id
    return result


def lane_http_steps(
    expanded: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Use native template type validation inside lanes; an If is not lane work."""
    request, shape = expanded[:2]
    request["error_policy"] = {"on_error": "fail"}
    shape["error_policy"] = {"on_error": "fail"}
    shape["override"]["template"]["inputs"][0]["type"] = "object"
    shape["override"]["template"]["text"] = "object"
    return [request, shape], [edge(request["step_id"], "success", shape["step_id"])]


def completion_edges(
    graph: SourceGraph, layout: ParallelLayout, ends: dict[int, str], outcomes: dict[int, list[str]]
) -> list[dict[str, Any]]:
    """Close lanes at their typed exit and continue once after the owning group."""
    result = []
    for index in graph.order:
        if index in layout.forks:
            result.append(
                {
                    "source": {"kind": "step", "id": ends[index]},
                    "outcome": {"name": outcomes[index][0]},
                    "target": {"kind": "group", "id": layout.forks[index]},
                    "rework": False,
                }
            )
            continue
        links = graph.links.get(index, [])
        for number, outcome in enumerate(outcomes[index]):
            target = links[number] if number < len(links) else None
            if target is None and index in layout.membership:
                result.append(
                    {
                        "source": {"kind": "step", "id": ends[index]},
                        "outcome": {"name": outcome},
                        "target": {"kind": "group_exit", **layout.membership[index]},
                        "rework": False,
                    }
                )
            else:
                result.append(
                    edge(ends[index], outcome, "done" if target is None else f"n{target:04d}")
                )
    for group in layout.groups:
        result.append(
            {
                "source": {"kind": "group", "id": group["group_id"]},
                "outcome": {"name": "success"},
                "target": {"kind": "step", "id": "done"},
                "rework": False,
            }
        )
    return result

"""Local credential classification; no platform runtime or local secret records."""

from __future__ import annotations

import re
from typing import Any

_SENSITIVE_KEY_MARKERS = (
    "password",
    "secret",
    "token",
    "bearer",
    "credential",
    "credentials",
    "api_key",
    "access_key",
    "private_key",
    "client_secret",
)
_AUTHENTICATION_FIELDS = frozenset({"authorization", "proxy_authorization", "cookie", "set_cookie"})
_AUTHENTICATION_SCHEMES = ("Bearer ", "Basic ", "Token ")
# Accept only complete generated state reads; never arbitrary template expressions.
_PORTABLE_PATH = re.compile(
    r"""state\.[\w-]+(?:\.[\w-]+|\[\s*(?:\d+|'(?:[^'\\]|\\.)*'|"(?:[^"\\]|\\.)*")\s*\])*"""
)


def _sensitive_key(key: Any) -> bool:
    normalized = str(key or "").strip().lower().replace("-", "_")
    compact = normalized.replace("_", "")
    return any(
        part in _AUTHENTICATION_FIELDS or part.endswith("_authorization")
        for part in normalized.split(".")
    ) or any(marker.replace("_", "") in compact for marker in _SENSITIVE_KEY_MARKERS)


def _portable_state_read(value: Any) -> bool:
    if not isinstance(value, str) or not value.strip().startswith("state."):
        return False
    selector = value.strip()
    return _PORTABLE_PATH.fullmatch(selector) is not None


def _portable_reference(value: Any) -> bool:
    if isinstance(value, dict):
        return set(value) == {"source"} and _portable_state_read(value["source"])
    if not isinstance(value, str):
        return False
    template = value.strip()
    for scheme in _AUTHENTICATION_SCHEMES:
        if template.casefold().startswith(scheme.casefold()):
            template = template[len(scheme) :].strip()
            break
    match = re.fullmatch(r"\{\{\s*(state\..*?)\s*\}\}", template)
    return match is not None and _portable_state_read(match.group(1).strip())

"""Target step/edge construction and strict source-option checks."""

from __future__ import annotations

from typing import Any

from .contracts import require


def step(step_id: str, kind: str, config: dict[str, Any]) -> dict[str, Any]:
    return {"step_id": step_id, "step_kind": kind, "override": {kind: config}}


def edge(source: str, outcome: str, target: str) -> dict[str, Any]:
    return {
        "source": {"kind": "step", "id": source},
        "outcome": {"name": outcome},
        "target": {"kind": "step", "id": target},
        "rework": False,
    }


def qualified_keys(
    data: dict[str, Any], allowed: set[str], path: str, *, code: str = "node_option_unsupported"
) -> None:
    require(not (set(data) - allowed), code, path, "An option has no qualified target equivalent.")

"""Translate a deliberately small expression grammar; extract authentication inputs."""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from typing import Any
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

from .contracts import ConversionBlocked, require
from .json_source import load_json
from .secrets import _sensitive_key

_PATH = re.compile(r"\$json((?:\.[A-Za-z_][A-Za-z0-9_]*|\[\d+\])*)")
_EXPRESSION = re.compile(r"=\s*\{\{\s*(.*?)\s*\}\}\s*", re.DOTALL)
_FIELD = re.compile(r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*")


def field_path(value: object, path: str) -> str:
    require(
        isinstance(value, str) and _FIELD.fullmatch(value),
        "field_unsupported",
        path,
        "A field path is not supported.",
    )
    assert isinstance(value, str)
    require(
        not {"__proto__", "constructor", "prototype"}.intersection(value.split(".")),
        "field_unsupported",
        path,
        "A field path is not supported.",
    )
    return value


def translate(value: Any, incoming: str, path: str, *, template: bool) -> Any:
    """Full $json paths preserve types; JavaScript and mixed templates are refused."""
    if isinstance(value, str):
        expression = _EXPRESSION.fullmatch(value)
        if expression:
            text = expression.group(1).strip()
            match = _PATH.fullmatch(text)
            if match:
                selector = incoming + match.group(1)
                return "{{ " + selector + " }}" if template else {"source": selector}
            try:
                literal = load_json(text)
            except (ValueError, RecursionError):
                literal = None
            else:
                return translate(literal, incoming, path, template=template)
            raise ConversionBlocked(
                "expression_unsupported",
                path,
                "An expression needs semantic adaptation.",
                "Translate against state selectors; do not execute JavaScript or copy it into templates.",
            )
        require(
            not value.startswith("=") and "{{" not in value and "{%" not in value,
            "expression_unsupported",
            path,
            "A source expression or target template needs explicit adaptation.",
        )
        return value
    if isinstance(value, dict):
        require(
            set(value) != {"source"},
            "literal_unsupported",
            path,
            "A literal collides with a target source-reference record.",
        )
        return {k: translate(v, incoming, path, template=template) for k, v in value.items()}
    if isinstance(value, list):
        return [translate(v, incoming, path, template=template) for v in value]
    return value


@dataclass
class CredentialInputs:
    """Store only generated input definitions, never original credential values."""

    fields: list[dict[str, Any]] = field(default_factory=list)

    def reference(self, value: Any, *, authorization: bool = False) -> str:
        require(
            isinstance(value, str),
            "credential_field_ambiguous",
            "parameters",
            "A credential-like field has an unqualified non-text value.",
        )
        prefix = ""
        if authorization and isinstance(value, str):
            for scheme in ("Bearer ", "Basic ", "Token "):
                if value.casefold().startswith(scheme.casefold()):
                    prefix = value[: len(scheme)]
                    break
        name = f"credential_{len(self.fields) + 1:04d}"
        self.fields.append(
            {
                "name": name,
                "type": "secret",
                "required": True,
                "description": "Supply the credential value after the authentication scheme already shown at its usage site."
                if prefix
                else "Supply the complete source field value, including any authentication scheme that was part of that field.",
            }
        )
        return prefix + "{{ state.inputs." + name + " }}"

    def body(self, value: Any) -> Any:
        if isinstance(value, dict):
            return {
                k: (v if isinstance(v, dict) and set(v) == {"source"} else self.reference(v))
                if _sensitive_key(k)
                else self.body(v)
                for k, v in value.items()
            }
        if isinstance(value, list):
            return [self.body(v) for v in value]
        return value

    def url(self, url: str, path: str) -> tuple[str, dict[str, str]]:
        try:
            parts = urlsplit(url)
            # Accessing port also validates its spelling and range.
            _ = parts.port
            valid = (
                parts.scheme in {"http", "https"}
                and parts.hostname
                and not parts.username
                and not parts.password
                and not parts.fragment
            )
        except ValueError:
            valid = False
        require(valid, "http_url_unsupported", path, "The URL needs explicit adaptation.")
        pairs = parse_qsl(parts.query, keep_blank_values=True)
        require(
            len({k for k, _ in pairs}) == len(pairs),
            "http_option_unsupported",
            path,
            "Repeated query parameters need explicit adaptation.",
        )
        secrets = {k: self.reference(v) for k, v in pairs if _sensitive_key(k)}
        public = [(k, v) for k, v in pairs if k not in secrets]
        return urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(public), "")), secrets


def literal_json(value: Any, path: str) -> Any:
    """A parsed JSON parameter is literal; never interpret strings inside it."""
    if isinstance(value, str):
        require(
            "{{" not in value and "{%" not in value,
            "expression_unsupported",
            path,
            "Literal source data collides with target template syntax.",
        )
    elif isinstance(value, dict):
        require(
            set(value) != {"source"},
            "literal_unsupported",
            path,
            "Literal data collides with a target source record.",
        )
        for nested in value.values():
            literal_json(nested, path)
    elif isinstance(value, list):
        for nested in value:
            literal_json(nested, path)
    return value


def contains_source(value: Any) -> bool:
    """Detect references structurally rather than guessing expression whitespace."""
    if isinstance(value, dict):
        return set(value) == {"source"} or any(contains_source(v) for v in value.values())
    return isinstance(value, list) and any(contains_source(v) for v in value)

